"""Recipe-specific step builder for generated catalogue entries."""

def build_generated_steps(title, norm_ings, meal_types, course, prep_t, cook_t):
    t=title.lower(); ing=[x.lower() for x in norm_ings]
    main=', '.join(norm_ings[:5]); garnish=next((x for x in norm_ings if x.lower() in {'coriander','fresh coriander','mint leaves','coconut','lemon juice'}), 'the listed garnish')
    base_items=[x for x in norm_ings if any(k in x.lower() for k in ('curd','dahi','milk','coconut milk','buttermilk','water'))]
    base_text=', '.join(base_items[:3]) or ', '.join(norm_ings[:3])
    core=[x for x in norm_ings if not any(k in x.lower() for k in ('salt','lemon','lime','mustard','cumin','turmeric','chilli','chili','pepper','masala','powder','oil','ghee','butter','coriander','curry leaf','hing','sugar','jaggery'))]
    core_text=', '.join(core[:4]) or ', '.join(norm_ings[:3])
    prep=max(2,int(prep_t)); cook=max(1,int(cook_t))
    def S(title,instruction,duration,tip): return {'step_number':0,'title':title,'instruction':instruction,'duration_mins':max(1,duration),'tip':tip}
    steps=[]
    # These checks come first because names like "roti noodles" and "roti frankie with chutney"
    # contain words that would otherwise trigger the flatbread/condiment branches.
    if any(k in t for k in ('sandwich','frankie','toast')):
        steps=[S('Prepare the Filling',f'Cook and season the filling ingredients for {title}: {", ".join(norm_ings[:6])}.',max(4,prep//2),'Keep the filling fairly dry so the bread or roti stays crisp.'),S('Prepare the Bread or Roti','Warm or toast the bread or roti according to the recipe.',max(2,prep//4),'Warm bread folds more easily.'),S('Assemble',f'Layer the recipe’s chutney, filling and listed toppings evenly for {title}, leaving the edges clear for folding.',max(2,prep//4),'Do not overfill; a compact filling is easier to toast.'),S('Toast and Finish',f'Toast the assembled {title.split("(")[0].strip()} until crisp outside and hot through, then cut and serve.',max(4,cook//2),'Press gently so the filling stays in place.') ]
    elif 'noodles' in t:
        steps=[S('Cut the Roti Ribbons',f'Cut the leftover roti/chapati component into thin ribbon-like strips for {title}.',max(3,prep//2),'Keep the strips similar in width so they heat evenly.'),S('Stir-Fry the Masala','Heat the listed oil and sauté the recipe’s aromatics, vegetables and spices until fragrant.',max(3,cook//3),'Use high enough heat to stir-fry without steaming the vegetables.'),S('Toss the Roti Noodles','Add the roti strips and toss continuously until coated with the masala and heated through.',max(3,cook//2),'Toss quickly so the roti stays distinct rather than becoming a paste.'),S('Finish and Serve','Add the listed coriander, lemon or finishing seasoning and serve immediately.',1,'Serve hot while the roti ribbons retain their texture.') ]
    else:
        if course=='Beverage' or any(k in t for k in ('lassi','chaas','solkadhi')):
            steps=[S('Prepare the Base',f'Measure {main}. Whisk the main liquid base—{base_text}—until smooth.',prep//2,'Use chilled ingredients and whisk until there are no lumps.'),S('Blend the Flavours',f'Add the remaining listed ingredients and blend or churn until evenly combined.',1,'Taste before adding more seasoning so the drink stays balanced.'),S('Adjust Consistency','Add the recipe liquid gradually until the drink reaches the intended pourable consistency.',1,'Add liquid gradually; over-thinning is difficult to correct.'),S('Chill and Serve',f'Pour into glasses and finish with {garnish}. Serve chilled.',1,'This recipe is served cool; do not use the generic hot-serving method.')]
        elif course=='Condiment' or 'chutney' in t or 'thecha' in t:
            steps=[S('Prepare Fresh Ingredients',f'Wash, dry and roughly chop the fresh ingredients for {title}: {main}.',prep//2,'Dry herbs and chillies give the finished condiment a cleaner texture.'),S('Toast the Dry Spices',f'Dry-roast any seeds or dry spices listed for {title} until fragrant, then cool them.',max(1,cook//4),'Stop as soon as the spices smell aromatic so they do not turn bitter.'),S('Grind or Crush',f'Grind or pound {", ".join(norm_ings[:6])} with the listed seasoning until the texture expected for {title} is reached.',max(2,cook//3),'Keep a coarse texture when this recipe is traditionally rustic.'),S('Balance and Finish','Adjust only with the listed salt, souring agent or sweetener, then finish with the listed garnish if present.',max(1,cook//3),'The condiment should taste balanced before serving.')]
        elif any(k in t for k in ('ladoo','ladu')):
            steps=[S('Roast the Base',f'Roast {", ".join(norm_ings[:2])} over low-medium heat, stirring until aromatic and evenly coloured.',max(4,cook//3),'Low heat prevents flour or rava from burning before it roasts through.'),S('Add Fat and Flavour',f'Add the listed fat and cardamom or other flavouring, then roast briefly until nutty.',max(3,cook//3),'The mixture should be moist enough to bind, not greasy.'),S('Sweeten and Bind',f'Mix in the listed sweetener and nuts: {", ".join(norm_ings[3:])}.',max(2,cook//5),'Cool until comfortable to handle before shaping.'),S('Shape the Ladoo','Press small portions firmly between your palms and roll into smooth ladoos.',max(3,cook//5),'If crumbly, use a little of the recipe’s listed warm fat or milk rather than water.')]
        elif any(k in t for k in ('kheer','payasam','rabdi')):
            steps=[S('Prepare the Main Ingredient',f'Rinse or roast {", ".join(norm_ings[:2])} as appropriate for {title}.',prep//2,'Roasting grains or vermicelli first removes a raw taste and improves aroma.'),S('Simmer the Milk',f'Bring the listed milk to a gentle simmer and cook {norm_ings[0]} until tender and the milk begins to thicken.',max(4,cook//2),'Stir the bottom frequently so the milk does not scorch.'),S('Sweeten and Perfume',f'Add {", ".join(norm_ings[2:])} according to the ingredient list and cook until the flavourings are fragrant.',max(2,cook//3),'Add delicate saffron and nuts near the end.'),S('Set and Serve','Turn off the heat while the pudding is slightly loose; it thickens as it cools. Finish with the listed nuts or saffron.',2,'Cooling changes the texture, so do not over-reduce the pudding on the stove.')]
        elif 'modak' in t:
            steps=[S('Cook the Coconut Filling','Cook the listed coconut and sweetener over low heat until moist and aromatic, then add cardamom if listed.',max(4,cook//3),'Stop before the filling dries out; it should hold together when pressed.'),S('Make the Rice Dough','Boil the listed water, stir in rice flour, cover briefly and knead into a soft dough while warm.',max(4,prep//2),'Keep the dough covered so its surface does not crack.'),S('Shape the Modak','Flatten dough portions into cups, fill with the coconut mixture and pinch into the characteristic pleated shape.',max(5,cook//4),'Wet fingertips lightly if needed and seal the top firmly.'),S('Steam','Arrange modaks in a greased steamer and steam until the rice shell is glossy and cooked through.',max(8,cook//2),'Leave space between modaks so steam circulates evenly.')]
        elif any(k in t for k in ('dhokla','handvo')):
            steps=[S('Prepare the Batter',f'Combine {", ".join(norm_ings[:5])} with the listed liquid and seasoning for {title}.',max(4,prep//2),'The batter should be thick enough to hold air but loose enough to spread.'),S('Activate the Batter','Add the recipe’s leavening or souring ingredients at the specified stage and mix gently.',max(1,prep//4),'Cook promptly after adding the raising agent for the best rise.'),S('Steam or Bake',f'Transfer the batter to the prepared steamer or pan and cook until the centre of {title.split("(")[0].strip()} is set.',max(8,cook//2),'Keep the heat stable and avoid opening the steamer or oven repeatedly.'),S('Temper and Cut','Prepare the listed seed-and-spice tempering, spread it over the cooked cake, rest briefly and cut.',max(3,cook//3),'Let the cake firm up before cutting so the pieces keep their shape.')]
        elif any(k in t for k in ('paratha','thepla','bhakri','roti','dhapate','ghavan','flatbread')):
            steps=[S('Make the Dough or Batter',f'Combine {", ".join(norm_ings[:5])} with the listed liquid and seasoning to make the dough or batter for {title}.',max(4,prep//2),'Add water gradually because different flours absorb differently.'),S('Rest and Portion','Rest the dough when required, then divide it into even portions.',max(2,prep//4),'Even portions cook at the same rate.'),S('Shape',f'Roll, pat or spread each portion into the characteristic shape of {title.split("(")[0].strip()}.',max(3,prep//4),'Keep the thickness reasonably even so the centre cooks through.'),S('Cook on the Tawa',f'Cook each piece on a medium-hot tawa, using the listed cooking fat only as specified for {title}.',max(5,cook//2),'Look for the characteristic toasted spots before flipping.'),S('Serve',f'Serve the finished {title.split("(")[0].strip()} hot with the recipe’s listed accompaniment.',1,'Keep cooked pieces covered briefly so they stay soft.')]
        elif any(k in t for k in ('vada','pakora','tikki','cutlet','fritter')):
            steps=[S('Prepare the Mixture',f'Cook or mash the main ingredients for {title}: {", ".join(norm_ings[:5])}. Mix with the listed seasoning.',max(4,prep//2),'The mixture should hold its shape when pressed.'),S('Shape the Pieces','Form even balls, patties or fritters according to the recipe.',max(3,prep//4),'Uniform pieces brown and cook evenly.'),S('Coat or Batter','Prepare the listed coating or batter, if any, and coat each piece evenly.',max(2,prep//4),'Let excess batter drip away for a thinner, crisper coating.'),S('Cook Until Crisp',f'Cook the pieces using the recipe’s listed method until {title.split("(")[0].strip()} has its characteristic browned exterior and a cooked centre.',max(6,cook//2),'Use steady medium heat so the outside does not burn before the centre cooks.'),S('Drain and Serve','Drain fried pieces if needed and serve with the recipe’s listed chutney or accompaniment.',1,'Serve soon after cooking for the best texture.')]
        elif any(k in t for k in ('pulao','biryani','bhaat','rice','chitranna','puliyodharai','bisi bele')):
            steps=[S('Prepare the Rice',f'Cook or cool the rice component as required for {title}; prepare {", ".join(norm_ings[:5])} before starting the tempering.',max(3,prep//2),'Separate rice grains give the best texture in tempered or fried rice dishes.'),S('Build the Tempering or Masala',f'Heat the listed cooking fat and bloom the recipe’s seeds, spices and aromatics until fragrant.',max(2,cook//4),'Add powdered spices over medium heat so they bloom without scorching.'),S('Cook the Main Mixture',f'Cook the main components—{core_text}—in the order appropriate for {title} until they reach the intended texture.',max(4,cook//2),'Taste the masala before combining it with rice.'),S('Combine and Finish','Fold the cooked rice into the prepared masala or layer it as required, then cover briefly so the flavours settle.',max(3,cook//4),'Fold gently so the rice grains remain intact.'),S('Garnish and Serve',f'Finish with {garnish} and serve {title.split("(")[0].strip()} hot.',1,'Use only the listed garnish and accompaniment so the finishing step matches the dish.')]
        elif any(k in t for k in ('dal','kadhi','rassa','curry','usal','bhaji','sabzi','kurma','gravy','pithla')):
            steps=[S('Prepare the Main Ingredients',f'Wash, chop, soak or pre-cook the main ingredients for {title}: {", ".join(norm_ings[:5])}.',max(4,prep//2),'Cut vegetables to similar sizes so they finish together.'),S('Build the Masala','Heat the listed cooking fat and cook the recipe’s aromatics, seeds and spices until fragrant.',max(3,cook//4),'Cook the masala until the raw aroma disappears before adding the main liquid.'),S('Cook Until Tender',f'Add the recipe’s water, stock, curd or coconut base and simmer {title.split("(")[0].strip()} until the main ingredient is tender and the gravy reaches the intended consistency.',max(6,cook//2),'Keep the simmer gentle once the ingredients are tender.'),S('Balance the Seasoning','Taste and adjust only with the listed salt, souring agent, sweetener or spice.',max(2,cook//5),'Balance sour, sweet and heat at the end.'),S('Finish and Serve',f'Turn off the heat, add {garnish} when listed, rest briefly and serve {title.split("(")[0].strip()}.',1,'Resting briefly lets the gravy and spices settle.')]
        elif any(k in t for k in ('sandwich','frankie','toast')):
            steps=[S('Prepare the Filling',f'Cook and season the filling ingredients for {title}: {", ".join(norm_ings[:6])}.',max(4,prep//2),'Keep the filling fairly dry so the bread or roti stays crisp.'),S('Prepare the Bread or Roti','Warm or toast the bread or roti according to the recipe.',max(2,prep//4),'Warm bread folds more easily.'),S('Assemble','Layer the recipe’s chutney, filling and listed toppings evenly, leaving the edges clear for folding.',max(2,prep//4),'Do not overfill; a compact filling is easier to toast.'),S('Toast and Finish',f'Toast the assembled {title.split("(")[0].strip()} until crisp outside and hot through, then cut and serve.',max(4,cook//2),'Press gently so the filling stays in place.')]
        elif 'noodles' in t:
            steps=[S('Prepare the Roti Noodles',f'Cut or tear the leftover roti/chapati component into thin ribbon-like strips for {title}.',max(3,prep//2),'Keep the strips similar in width so they heat evenly.'),S('Cook the Masala','Heat the listed oil and sauté the recipe’s aromatics, vegetables and spices until fragrant.',max(3,cook//3),'Use high enough heat to stir-fry without steaming the vegetables.'),S('Toss the Roti Ribbons','Add the roti strips and toss continuously until coated with the masala and heated through.',max(3,cook//2),'Toss quickly so the roti stays distinct rather than becoming a paste.'),S('Finish and Serve','Add the listed coriander, lemon or finishing seasoning and serve immediately.',1,'This dish is best served hot while the roti ribbons retain their texture.')]
        else:
            steps=[S(f'Prepare {title.split("(")[0].strip()}',f'Measure and prepare the main ingredients for {title}: {main}.',prep,'Keep the main ingredient ready before starting the cooking stage.'),S('Cook the Main Components',f'Cook the ingredients for {title} in the order required by their cooking time, adding delicate ingredients later.',max(1,cook//2),'Watch the texture of the main ingredient as well as the clock.'),S('Combine and Season',f'Combine the cooked components of {title} and balance only the listed seasoning.',max(1,cook//3),'Taste near the end because cooking can concentrate seasoning.'),S(f'Finish {title.split("(")[0].strip()}',f'Finish {title} with {garnish} and serve at the intended texture and temperature.',max(1,cook//5),'Use the recipe’s listed finishing ingredient so this step stays specific to the dish.')]
    for i,x in enumerate(steps,1): x['step_number']=i
    return steps
